{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table datalake_db.kaya.dwh_kaya_daily_offtake_report as WITH SKU_Master as ( select * from ( select distinct marketplace_sku,ean from datalake_db.kaya.Final_SKU_master union all select distinct parent,ean from datalake_db.kaya.Final_SKU_master union all select distinct pid,ean from datalake_db.kaya.Final_SKU_master union all select distinct old_sku,ean from datalake_db.kaya.Final_SKU_master union all select distinct marico_code,ean from datalake_db.kaya.Final_SKU_master ) qualify row_number() over(partition by lower(trim(marketplace_sku)) order by 1)=1 ), base_data AS ( SELECT Upper(CASE WHEN channel_id = 1 THEN \'amazon\' WHEN channel_id = 2 THEN \'flipkart\' WHEN channel_id = 25 THEN \'nykaa\' WHEN channel_id = 27 THEN \'blinkit\' WHEN channel_id = 28 THEN \'myntra\' WHEN channel_id = 39 THEN \'flipkart grocery\' WHEN channel_id = 65 THEN \'swiggy\' WHEN channel_id = 109 THEN \'zepto\' WHEN channel_id = 160 THEN \'tira\' WHEN channel_id = 181 THEN \'google_ads\' WHEN channel_id = 183 THEN \'facebook_ads\' WHEN channel_id = 194 THEN \'youtube\' WHEN channel_id = 198 THEN \'google_dv360_ads\' ELSE \'other\' END) AS channel, CAST(DATE AS DATE) AS date, trim(upper(sku)) as SKU, EAN, MAX(IFNULL(price, 0)) AS price, MAX(availability) AS availability FROM DEV_DB_SHR.VENDOR.TRN_DQ_MARICO_AVAILABILITY_MARKETPLACE a left join SKU_Master s on lower(trim(marketplace_sku)) = lower(trim(a.sku)) WHERE LOWER(brand) = \'kaya\' GROUP BY 1, 2,3,4 ) , base as( select DATE::date as DATE ,ASIN ,PLATFORM_NAME ,upper(coalesce(fsm1.PRODUCT_TITLE, fsm.PRODUCT_TITLE,od.PRODUCT_TITLE)) PRODUCT_TITLE ,od.EAN ,SHIPPED_UNIT ,MATERIAL_CODE ,MATERIAL_GROUP_CODE ,MATERIAL_GROUP_DESC ,UOM_REPORTING ,VOL_PER_UNIT ,VOL_IN_LIT ,VOL_IN_RUM ,INDEXRATE ,INDEXBPM ,CATEGORY ,od.date::date as month ,indexbpm as ACTUAL_NUMERATOR ,upper(coalesce(fsm1.SUB_CATEGORY, fsm.SUB_CATEGORY)) SUB_CATEGORY ,upper(coalesce(fsm1.PRODUCT_NAME, fsm.PRODUCT_NAME)) PRODUCT_NAME ,case when ifnull(upper(\"Priority Product\"),\'\') = \'YES\' then \'YES\' else \'NO\' end as Priority_Product from PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY od left join ( select * from datalake_db.kaya.trn_kaya_sku_mapping qualify row_number() over(partition by EAN order by 1) = 1 )sm on od.ean = sm.ean left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(ean)) order by 1) = 1 )fsm on od.ean = fsm.ean left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_SKU)) order by 1) = 1 )fsm1 on upper(od.asin) = upper(fsm1.marketplace_SKU) where upper(material_group_code) in (\'KAYA_GM\' ,\'KAYA_ML\') ), Months as ( select last_day(dateadd(month,1,month)) Date, PLATFORM_NAME Channel, sum(ifnull(INDEXBPM,0)) month_INDEXBPM, from Base group by 1,2 ) select bs.*, div0(ifnull(month_INDEXBPM,0),count(*) over(partition by last_day(bs.month), lower(bs.PLATFORM_NAME))) as Last_Month_INDEXBPM, coalesce(bd.availability,bd1.availability) as availability from Base bs left join Months ms on last_day(bs.month) = ms.date and lower(bs.PLATFORM_NAME) = lower(ms.Channel) left join (select date ,channel ,ean ,availability from base_data qualify row_number() over(partition by date,lower(channel),lower(ean) order by 1) = 1 and ean is not null )bd on (bs.DATE) = bd.date and lower(bs.PLATFORM_NAME) = lower(bd.channel) and bs.ean = bd.ean left join (select date ,channel ,sku ,availability from base_data qualify row_number() over(partition by date,lower(channel),lower(sku) order by 1) = 1 and sku is not null )bd1 on (bs.DATE) = bd1.date and lower(bs.PLATFORM_NAME) = lower(bd1.channel) and lower(bs.asin) = lower(bd1.sku) ; CREATE OR REPLACE TABLE datalake_db.kaya.dwh_kaya_ecom_PandL AS WITH MT_ECOM_NR as ( SELECT inv_date AS date, channel_name, coalesce(p1.SUB_CATEGORY,p2.SUB_CATEGORY,p3.SUB_CATEGORY) as SubCategory, case when lower(sub_channel_name) like \'%flipkart%\' then \'FLIPKART\' when lower(sub_channel_name) like \'%grofers%\' then \'BLINKIT\' when lower(sub_channel_name) like \'%innovative retail%\' then \'BIG BASKET\' when lower(sub_channel_name) like \'%kiranakart tech%\' then \'ZEPTO\' when lower(sub_channel_name) like \'%nykaa%\' then \'NYKAA\' when upper(sub_channel_name) like \'%RK WORLDINFOCOM%\' then \'AMAZON\' when upper(sub_channel_name) like \'%SCOOTSY LOGISTICS%\' then \'SWIGGY\' else upper(sub_channel_name) end as new_Channel ,ifnull(SUM(quantity * mrp),0) * 0.38 AS NR FROM prd_db_shr.public.TRN_PRIMARY_SALES_INVOICES_DETAILED a LEFT JOIN datalake_db_shr.public.TRN_MST_CUSTOMER_PWBI b ON a.customer = b.customer_code AND b.company_code = \'MIL\' AND b.latest_record_ind = 1 LEFT JOIN datalake_db_shr.public.TRN_MST_MATERIAL_PWBI c ON a.sku_code = c.material_code AND c.company_code = \'MIL\' AND c.latest_record_ind = 1 left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marico_code)) order by 1) = 1 )p1 on trim(upper(a.sku_code)) = upper(trim(p1.marico_code)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(parent)) order by 1) = 1 )p2 on trim(upper(a.sku_code)) = upper(trim(p2.parent)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(old_sku)) order by 1) = 1 )p3 on trim(upper(a.sku_code)) = upper(trim(p3.old_sku)) WHERE b.sub_channel_group = \'B2C\' AND b.channel_name in (\'MT\',\'E-Commerce\') AND c.material_group_code IN (\'KAYA_ML\', \'KAYA_GM\') GROUP BY 1,2,3,4 order by 1 desc ), ACTUALS as ( select date as month_date, upper(SubCategory)SubCategory, \'Modern Trade\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Modern Trade Total\' Net_Realization, \'2.NR Sales\' Metric, new_Channel channel, \'NR\' TYPE, sum(ifnull(nr,0))/100000 Actual_Numerator, null Actual_Denominator, null as tertiary from MT_ECOM_NR where channel_name = \'MT\' group by 1,2,3,4,5,6,7 union all select date, upper(SubCategory), \'ECOM\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Ecom Total\' Net_Realization, \'2.NR Sales\' Metric, new_Channel, \'NR\' TYEP, sum(ifnull(nr,0))/100000 as Actual_Numerator, null as Actual_Denominator, null as tertiary from MT_ECOM_NR where channel_name = \'E-Commerce\' group by 1,2,3,4,5,6,7 UNION ALL select order_date::date as Date, upper(SUB_CATEGORY), \'DTC\' as Final_marketplace, \'DTC\' as marketplace, \'DTC Total\' Net_Realization, \'2.NR Sales\' AS Metric, \'DTC\' as channel, \'NR\' TYEP, sum((ifnull(selling_price,0) - ifnull(selling_price*18/118 ,0)) * 0.975)/100000 as Actual_Numerator, NULL AS Actual_Denominator, null as tertiary from datalake_db.kaya.dwh_unicommerce_fact_items s left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_sku)) order by 1) = 1 )p2 on trim(upper(s.sku)) = upper(trim(p2.marketplace_sku)) where courierstatus = \'DELIVERED\' and s.marketplace = \'KAYASCIENCE_SHOPIFY\' and not((s.product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1,2 UNION ALL select date::date as Date ,upper(SUB_CATEGORY) ,\'ECOM\' as Final_marketplace, \'ECOM+MT\' as marketplace, \'Primary Ecom Total\' Net_Realization, \'2.NR Sales\' Metric, upper(PLATFORM_NAME) as new_Channel, \'NR\' TYEP, null as Actual_Numerator, null as Actual_Denominator, sum(ifnull(indexbpm,0)) tertiary from datalake_db.kaya.dwh_kaya_daily_offtake_report group by 1,2,3,4,5,6,7 UNION ALL select order_date::date as Date, SUB_CATEGORY, \'DTC\' as Final_marketplace, \'DTC\' as marketplace, \'Primary DTC Total\' Net_Realization, \'2.NR Sales\' AS Metric, \'DTC\' as channel, \'NR\' TYEP, null as Actual_Numerator, NULL AS Actual_Denominator, sum((ifnull(selling_price,0)))/100000 as tertiary from datalake_db.kaya.dwh_unicommerce_fact_items s left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_sku)) order by 1) = 1 )p2 on trim(upper(s.sku)) = upper(trim(p2.marketplace_sku)) where courierstatus = \'DELIVERED\' and s.marketplace = \'KAYASCIENCE_SHOPIFY\' and not((s.product_name) in (\'sling bag\',\'Kaya Gift Box\',\'Keychain\',\'FestiveGWPBoxWithoutHB\',\'vanitybox\',\'kaya Science Gift Pouch\')) group by 1,2 UNION ALL ( select MONTH as Date, subcategory SUB_CATEGORY, \'MODERN TRADE\' as Final_marketplace, \'MODERN TRADE\' as marketplace, \'Primary MT Total\' Net_Realization, \'2.NR Sales\' AS Metric, upper(CHAIN_NAME) as channel, \'NR\' TYEP, null as Actual_Numerator, NULL AS Actual_Denominator, sum((ifnull(Offtake_Index_BPM_LAC,0))) as tertiary from ( SELECT TO_DATE(TO_VARCHAR(MONTH), \'YYYYMM\') AS MONTH, ASSORTMENT_WORK_SKU, CHAIN_NAME, SUBCATEGORY, sum(CASE WHEN DATA_TYPE = \'Off-take\' THEN ifnull(INDEX_BPM_LAC,0) END) AS Offtake_Index_BPM_LAC FROM PRD_DB_SHR.PUBLIC.TRN_MTB2C_SECONDARY_VS_OFFTAKE where DATA_TYPE = \'Off-take\' and upper(brand_code) in (\'KAYA_ML\',\'KAYA_GM\') GROUP BY 1, 2, 3, 4 ) group by 1,2,3,4,5,6,7,8 )) , Targets AS ( WITH monthly_targets AS ( SELECT TO_DATE(month, \'DD-MM-YYYY\') AS month_start, LAST_DAY(TO_DATE(month, \'DD-MM-YYYY\')) AS month_end, CASE WHEN LOWER(metric) = \'nr\' THEN \'2.NR Sales\' ELSE NULL END AS metric, upper(channel) AS marketplace, upper(chain) Chain , TRY_CAST(target AS FLOAT) AS target_value FROM datalake_db.kaya.trn_pandl_targets WHERE target IS NOT NULL ), day_generator AS ( SELECT SEQ4() AS day_offset FROM TABLE(GENERATOR(ROWCOUNT => 31)) ), expanded_days AS ( SELECT mt.month_start, mt.month_end, mt.metric, mt.Chain, mt.marketplace, mt.target_value, DATEADD(DAY, dg.day_offset, mt.month_start) AS day_date, DAY(mt.month_end) AS num_days_in_month FROM monthly_targets mt JOIN day_generator dg ON DATEADD(DAY, dg.day_offset, mt.month_start) <= mt.month_end ) SELECT day_date AS month, metric, Chain, marketplace, CASE WHEN upper(marketplace) ILIKE \'%TOTAL\' THEN TRIM(REPLACE(marketplace, \'TOTAL\', \'\')) ELSE marketplace END AS Final_marketplace, target_value / num_days_in_month AS Target_Numerator, NULL AS Target_Denominator FROM expanded_days t left join ( select Net_Realization ,case when last_day(current_date) = last_day(max(month_date)) then max(month_date) else last_day(DATEADD(DAY, -1, DATE_TRUNC(\'MONTH\', CURRENT_DATE))) end as max_date from ACTUALS group by 1 ) on lower(Net_Realization) = lower(t.marketplace) WHERE metric IS NOT NULL and day_date <= max_date ORDER BY marketplace, metric, month ) select a.month_date as month_date, COALESCE(a.month_date, t.month)::DATE AS Month, a.SubCategory, COALESCE(a.metric, t.metric) AS metric, upper(COALESCE(channel,Chain)) as new_channel, upper(coalesce(a.Final_marketplace,t.Final_marketplace)) as Final_marketplace, coalesce(type,\'NR\') as type, upper(COALESCE(a.marketplace, t.marketplace)) AS marketplace, upper(COALESCE(Net_Realization, t.marketplace)) AS channel, a.Actual_Numerator::FLOAT AS Actual_Numerator, a.Actual_Denominator::FLOAT AS Actual_Denominator, a.tertiary as tertiary, DIV0(COALESCE(t.Target_Numerator, 0),COUNT(*) OVER (PARTITION BY COALESCE(a.month_date, t.month), COALESCE(LOWER(a.metric), LOWER(t.metric)), COALESCE(LOWER(Net_Realization), LOWER(t.marketplace)), COALESCE(LOWER(channel), LOWER(t.chain)) )) AS Target_Numerator, t.Target_Denominator::FLOAT AS Target_Denominator FROM Actuals a FULL OUTER JOIN Targets t ON a.month_date = t.month AND LOWER(a.metric) = LOWER(t.metric) and lower(Net_Realization) = lower(t.marketplace) and lower(channel) = lower(t.chain) ; Create or replace table datalake_db.kaya.dwh_kaya_NR_DRR_Fact_items as WITH RECURSIVE month_ends AS ( SELECT DATE_TRUNC(\'MONTH\', DATE \'2024-06-30\') + INTERVAL \'1 MONTH\' - INTERVAL \'1 DAY\' AS DATE UNION ALL SELECT DATE_TRUNC(\'MONTH\', DATE + INTERVAL \'1 MONTH\') + INTERVAL \'1 MONTH\' - INTERVAL \'1 DAY\' FROM month_ends WHERE DATE < CURRENT_DATE ), Month_Level_Data as ( select last_day(month) Date1 ,upper(ifnull(SUBCATEGORY,\'Others\')) as SUBCATEGORY ,upper(coalesce(NEW_CHANNEL,\'Others\')) NEW_CHANNEL ,upper(final_marketplace) as Channel ,sum(ifnull(ACTUAL_NUMERATOR,0)) as ACTUAL_NUMERATOR from datalake_db.kaya.dwh_kaya_ecom_PandL where type = \'NR\' and (METRIC) = \'2.NR Sales\' and CHANNEL IN (\'DTC TOTAL\', \'ECOM TOTAL\', \'MODERN TRADE TOTAL\', \'DTC\') group by 1,2,3,4 ), combine as ( select * from month_ends , Month_Level_Data ) select c.*, Channel as FINAL_MARKETPLACE ,case when last_day(date1) = last_day(current_date) then day(month_date1) else day(last_day(date1)) end as drr_d ,DATE_TRUNC(\'MONTH\', DATE)as Month_Start_Date from combine c left join ( select upper(final_marketplace) as final_marketplace, max(month) as month_date1 from datalake_db.kaya.dwh_kaya_ecom_PandL where month_date is not null and type = \'NR\' and (METRIC) = \'2.NR Sales\' and CHANNEL IN (\'DTC TOTAL\', \'ECOM TOTAL\', \'MODERN TRADE TOTAL\', \'DTC\') group by 1 )l3 on c.Channel = l3.final_marketplace; create or replace table datalake_db.kaya.dwh_kaya_secondary_offtake_report as with base as ( select a.month_date ,a.material_group_code ,a.material_code ,case when lower(c.customer_name ) like \'%flipkart%\' then \'FLIPKART\' when lower(c.customer_name ) like \'%grofers%\' then \'BLINKIT\' when lower(c.customer_name ) like \'%innovative retail%\' then \'BIG BASKET\' when lower(c.customer_name ) like \'%kiranakart tech%\' then \'ZEPTO\' when lower(c.customer_name ) like \'%nykaa%\' then \'NYKAA\' when upper(c.customer_name ) like \'%RK WORLDINFOCOM%\' then \'AMAZON\' when upper(c.customer_name ) like \'%SCOOTSY LOGISTICS%\' then \'SWIGGY\' when upper(c.customer_name ) like \'%FATEHPURIA HYGIENE PRIVATE LIMITED%\' then \'MYNTRA\' else upper(c.customer_name ) end as customer_name ,c.channel_name ,map.category ,fsm.Sub_Category ,fsm.product_title ,a.pri_actuals_vol_rum*b.turnover as secondary_value from datalake_db_shr.public.TRN_DWH_BPM_DIST_SKU_DAILY_PWBI a left join datalake_db_shr.public.TRN_DWH_SAP_INDEX_TURNOVER_MONTHWISE_PWBI b on a.index_wid=b.Row_wid left join datalake_db_shr.public.TRN_MST_CUSTOMER_PWBI c on a.customer_wid=c.row_wid left join ( select material_code,category from PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY qualify row_number() over(partition by lower(material_code) order by 1) =1 )map on lower(map.material_code) = lower(a.material_code) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marico_code)) order by 1) = 1 )fsm on upper(a.material_code) = upper(fsm.marico_code) where c.channel_name in (\'E-Commerce\',\'Q-Commerce\') and upper(material_group_code) in (\'KAYA_ML\',\'KAYA_GM\') ), Months as ( select last_day(dateadd(month,1,month_date)) Date, customer_name Channel, sum(ifnull(SECONDARY_VALUE,0)) month_INDEXBPM from Base group by 1,2 ) select bs.*, div0(ifnull(month_INDEXBPM,0),count(*) over(partition by last_day(bs.month_date), lower(bs.customer_name))) as Last_Month_SECONDARY_VALUE from Base bs left join Months ms on last_day(bs.month_date) = ms.date and lower(bs.customer_name) = lower(ms.Channel) ; Create or replace table datalake_db.kaya.dwh_kaya_primary_secondary_monthly_report as with offtake as ( select (date) month ,upper(platform_name) platform_name ,material_code ,sum(ifnull(indexbpm,0)) indexbpm ,sum(shipped_unit) as shipped_unit from datalake_db.kaya.dwh_kaya_daily_offtake_report group by 1,2,3 ), secondary as ( select (month_date) as month ,upper(customer_name) channel_name ,material_code ,sum(ifnull(secondary_value,0))/100000 secondary_value from datalake_db.kaya.dwh_kaya_secondary_offtake_report group by 1,2,3 ), Final_Result as ( select coalesce(o.month,s.month) Date, coalesce(upper(platform_name),upper(s.channel_name)) channel, coalesce(upper(o.material_code),upper(s.material_code)) material_code, o.indexbpm, s.secondary_value from offtake o full outer join secondary s on o.month = s.month and upper(platform_name) = upper(s.channel_name) and upper(o.material_code) = upper(s.material_code) ) select a.*,coalesce(p1.SUB_CATEGORY,p2.SUB_CATEGORY,p3.SUB_CATEGORY) as SubCategory ,coalesce(p1.PRODUCT_TITLE,p2.PRODUCT_TITLE,p3.PRODUCT_TITLE) as PRODUCT_TITLE from Final_Result a left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marico_code)) order by 1) = 1 )p1 on trim(upper(a.material_code)) = upper(trim(p1.marico_code)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(parent)) order by 1) = 1 )p2 on trim(upper(a.material_code)) = upper(trim(p2.parent)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(old_sku)) order by 1) = 1 )p3 on trim(upper(a.material_code)) = upper(trim(p3.old_sku)) ; create or replace table datalake_db.kaya.dwh_kaya_offtake_marketing_Data as with Base_Spends as ( -- select client_id, -- channel_id, -- \'AMAZON\' as Channel, -- country, -- campaign_id, -- campaign_name, -- sku_name, -- program_type, -- report_date, -- sum(impression)AS impression, -- sum(click) AS clicks, -- sum(orders) AS orders, -- sum(spend) AS spends, -- sum(sale) AS sales -- from DEV_DB_SHR.VENDOR.TRN_MEDIA_CAMPAIGN_DATA -- ( -- select s.*, -- coalesce(concat(campaigns,\'kaya\'),campaign_name) as check_campaign_name -- from -- (select * -- from DEV_DB_SHR.VENDOR.TRN_MEDIA_CAMPAIGN_DATA -- where channel_id in (27,65,109,28) -- ) s -- left join ( -- select -- distinct trim(lower(campaigns)) campaigns -- from datalake_db.kaya.dwh_campaigns_to_include -- )g -- on trim(lower(s.campaign_name)) = trim(lower(g.campaigns)) -- ) -- where channel_id in (1) and lower(record_type) = \'campaign\' -- group by 1,2,3,4,5,6,7,8,9 -- UNION ALL select client_id, channel_id, case when channel_id = 28 then \'MYNTRA\' when channel_id = 65 then \'SWIGGY\' when channel_id = 109 then \'ZEPTO\' when channel_id = 27 then \'BLINKIT\' when channel_id = 1 then \'AMAZON\' end as Channel, country, campaign_id, campaign_name, sku_name, program_type, report_date, sum(ifnull(impression,0))AS impression, sum(ifnull(click,0)) AS clicks, sum(ifnull(orders,0)) AS orders, sum(ifnull(spend,0)) AS spends, sum(ifnull(sale,0)) AS sales from ( select s.*, coalesce(concat(campaigns,\'kaya\'),campaign_name) as check_campaign_name from (select * from DEV_DB_SHR.VENDOR.TRN_MEDIA_CAMPAIGN_DATA where channel_id in (1,27,65,109,28) ) s left join ( select distinct trim(lower(campaigns)) campaigns from datalake_db.kaya.dwh_campaigns_to_include )g on trim(lower(s.campaign_name)) = trim(lower(g.campaigns)) ) where lower(check_campaign_name) LIKE \'%kaya%\' and lower(record_type) = \'campaign\' group by 1,2,3,4,5,6,7,8,9 ), Month_Spends as ( select last_day(dateadd(month,1,report_date)) Date, Channel, sum(ifnull(spends,0)) month_spends from Base_Spends group by 1,2 ) select bs.*, div0(ifnull(month_spends,0),count(*) over(partition by last_day(bs.report_date), lower(bs.Channel))) as Last_Month_Spends from Base_Spends bs left join Month_Spends ms on last_day(bs.report_date) = date and lower(bs.Channel) = lower(ms.Channel) ;",
                    "transaction": true
                }
            ) }}
